def issue(exc, where=''):
    key = exc.key if isinstance(exc, DataError) else 'permission' if isinstance(exc, PermissionError) else 'missing_file' if isinstance(exc, FileNotFoundError) else 'unexpected'
    data = MESSAGES.get(key, MESSAGES['unexpected'])
    return {'code': key, 'where': str(where), 'detail': exc.detail if isinstance(exc, DataError) else f'{type(exc).__name__}: {exc}',
            'zh': dict(zip(('title', 'why', 'fix'), data[:3])), 'en': dict(zip(('title', 'why', 'fix'), data[3:]))}
